/* Icons for the whole site (generated by tools/icons/build.js — edit emoji-map.json, not this file).
   Icons: Lucide (https://lucide.dev), ISC licence.
   The site's text is written with emojis; this file shows each one as a clean line icon instead.
   It works on everything the site draws, including text added later by the app. */
(function () {
  "use strict";
  var SPRITE = __SPRITE__;
  var MAP = __MAP__;
  // one emoji: a flag pair, or a pictograph with optional variation selector / keycap and ZWJ joins; plus ★ ☆
  var RE = /(?:[\u{1F1E6}-\u{1F1FF}]{2}|\p{Extended_Pictographic}(?:️|⃣)?(?:‍\p{Extended_Pictographic}️?)*|[★☆])️?/gu;
  var KEEP = { "↔": 1, "©": 1, "®": 1, "™": 1 }; // ↔ © ® ™ stay as text
  var SKIP = { SCRIPT: 1, STYLE: 1, TEXTAREA: 1, INPUT: 1, svg: 1, SVG: 1, CODE: 1, NOSCRIPT: 1 };
  var ATTRS = ["title", "aria-label", "placeholder", "alt"];

  function IC(name, cls) {
    return '<svg class="ic' + (cls ? " ic-" + cls : "") + '" aria-hidden="true" focusable="false"><use href="#i-' + name + '"></use></svg>';
  }
  function spec(e) { var v = MAP[e]; if (v === undefined) v = MAP[e.replace(/️/g, "")]; return v; }
  // plain text without emojis (for canvas, page titles, alerts, speech)
  function strip(s) {
    return String(s).replace(RE, function (e) { return KEEP[e] ? e : ""; }).replace(/[ \t]{2,}/g, " ").replace(/^\s+/, function (m) { return m.indexOf("\n") >= 0 ? m : ""; });
  }
  // true only if the text has an emoji that must change (↔ © ® ™ stay as they are, so they never loop)
  function needs(s) { var m = String(s).match(RE); if (!m) return false; for (var i = 0; i < m.length; i++) if (!KEEP[m[i]]) return true; return false; }
  function convertText(node) {
    var t = node.nodeValue; if (!t || !needs(t)) return;
    var p = node.parentNode; if (!p) return;
    if (p.nodeName === "OPTION" || p.nodeName === "TITLE") { node.nodeValue = strip(t); return; }
    var frag = document.createDocumentFragment(), last = 0, m;
    RE.lastIndex = 0;
    while ((m = RE.exec(t))) {
      var e = m[0]; if (KEEP[e]) continue;
      if (m.index > last) frag.appendChild(document.createTextNode(t.slice(last, m.index)));
      var v = spec(e);
      if (v) {
        var parts = v.split("|"), tmp = document.createElement("span");
        tmp.innerHTML = IC(parts[0], parts[1]); frag.appendChild(tmp.firstChild);
      } else if (window.console && console.debug) console.debug("icons.js: no icon for", e);
      last = m.index + e.length;
      // an emoji removed at the very start leaves no stray space
      if (!v && t.charAt(last) === " " && last - e.length === 0) last++;
    }
    if (last < t.length) frag.appendChild(document.createTextNode(t.slice(last)));
    p.replaceChild(frag, node);
  }
  function convertAttrs(el) {
    for (var i = 0; i < ATTRS.length; i++) { var a = el.getAttribute && el.getAttribute(ATTRS[i]); if (a && needs(a)) el.setAttribute(ATTRS[i], strip(a)); }
  }
  function walk(root) {
    if (!root) return;
    if (root.nodeType === 3) { if (!skipped(root.parentNode)) convertText(root); return; }
    if (root.nodeType !== 1) return;
    convertAttrs(root); // placeholders and titles of text boxes too
    if (SKIP[root.nodeName] || skipped(root)) return;
    var tw = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
      acceptNode: function (n) { if (n.nodeType === 1 && SKIP[n.nodeName]) { convertAttrs(n); return NodeFilter.FILTER_REJECT; } return NodeFilter.FILTER_ACCEPT; }
    });
    var texts = [], n;
    while ((n = tw.nextNode())) { if (n.nodeType === 3) { if (needs(n.nodeValue)) texts.push(n); } else convertAttrs(n); }
    texts.forEach(convertText);
  }
  function skipped(el) { for (var e = el; e && e.nodeType === 1; e = e.parentNode) { if (SKIP[e.nodeName] || e.isContentEditable) return true; } return false; }

  function start() {
    var holder = document.createElement("div");
    holder.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" style="position:absolute;width:0;height:0;overflow:hidden" aria-hidden="true">' + SPRITE + "</svg>";
    document.body.insertBefore(holder.firstChild, document.body.firstChild);
    walk(document.body);
    var busy = false;
    new MutationObserver(function (list) {
      if (busy) return; busy = true;
      try {
        for (var i = 0; i < list.length; i++) {
          var r = list[i];
          if (r.type === "characterData") { if (!skipped(r.target.parentNode)) convertText(r.target); }
          else if (r.type === "attributes") convertAttrs(r.target);
          else for (var j = 0; j < r.addedNodes.length; j++) walk(r.addedNodes[j]);
        }
      } finally { busy = false; }
    }).observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ATTRS });
  }
  // pop-up messages and canvas drawings (certificate, photo badge, 3D labels) can't show icons: plain text there
  ["alert", "confirm", "prompt"].forEach(function (k) {
    var f = window[k]; if (!f) return;
    window[k] = function (msg) { var a = Array.prototype.slice.call(arguments); a[0] = msg == null ? msg : strip(msg); return f.apply(window, a); };
  });
  if (window.CanvasRenderingContext2D) ["fillText", "strokeText", "measureText"].forEach(function (k) {
    var f = CanvasRenderingContext2D.prototype[k];
    CanvasRenderingContext2D.prototype[k] = function (t) { var a = Array.prototype.slice.call(arguments); a[0] = strip(t); return f.apply(this, a); };
  });
  window.IC = IC;
  window.Icons = { IC: IC, strip: strip, convert: walk };
  if (document.body) start(); else document.addEventListener("DOMContentLoaded", start);
})();
